#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <ctype.h>

#define MAX_TEMPLATE 4096
#define MAX_FIELD 256
#define MAX_CMD 8192

typedef struct {
    char smtp_host[MAX_FIELD];
    char smtp_port[8];
    char from_addr[MAX_FIELD];
    char template_dir[MAX_FIELD];
    int use_shell_transport;
} mail_config_t;

typedef struct {
    char to[MAX_FIELD];
    char subject[MAX_FIELD];
    char username[MAX_FIELD];
    char token[MAX_FIELD];
} mail_context_t;

static int load_config(mail_config_t *cfg) {
    const char *host = getenv("SMTP_HOST");
    const char *port = getenv("SMTP_PORT");
    const char *from = getenv("SMTP_FROM");
    const char *tdir = getenv("TEMPLATE_DIR");
    const char *transport = getenv("MAIL_TRANSPORT");

    if (!host || !port || !from || !tdir) return -1;

    strncpy(cfg->smtp_host, host, MAX_FIELD - 1);
    strncpy(cfg->smtp_port, port, 7);
    strncpy(cfg->from_addr, from, MAX_FIELD - 1);
    strncpy(cfg->template_dir, tdir, MAX_FIELD - 1);

    cfg->use_shell_transport = (transport && strcmp(transport, "sendmail") == 0) ? 1 : 0;
    return 0;
}

static int sanitize_email(const char *email) {
    if (!email || strlen(email) > 254) return 0;
    const char *at = strchr(email, '@');
    if (!at || at == email) return 0;
    if (!strchr(at + 1, '.')) return 0;
    for (const char *p = email; *p; p++) {
        if (*p == '\n' || *p == '\r') return 0;
    }
    return 1;
}

static int sanitize_field(const char *field) {
    if (!field) return 0;
    for (const char *p = field; *p; p++) {
        if (*p == '\n' || *p == '\r') return 0;
    }
    return 1;
}

static char* render_template(const char *tmpl, const mail_context_t *ctx) {
    char *output = calloc(MAX_TEMPLATE * 2, 1);
    if (!output) return NULL;

    const char *src = tmpl;
    char *dst = output;
    size_t remaining = MAX_TEMPLATE * 2 - 1;

    while (*src && remaining > 0) {
        if (src[0] == '{' && src[1] == '{') {
            const char *end = strstr(src + 2, "}}");
            if (end) {
                char varname[64] = {0};
                size_t vlen = end - (src + 2);
                if (vlen < 63) {
                    strncpy(varname, src + 2, vlen);
                    /* trim whitespace */
                    char *v = varname;
                    while (*v == ' ') v++;
                    char *ve = v + strlen(v) - 1;
                    while (ve > v && *ve == ' ') *ve-- = '\0';

                    const char *replacement = NULL;
                    if (strcmp(v, "username") == 0) replacement = ctx->username;
                    else if (strcmp(v, "to") == 0) replacement = ctx->to;
                    else if (strcmp(v, "token") == 0) replacement = ctx->token;
                    else if (strcmp(v, "subject") == 0) replacement = ctx->subject;
                    else replacement = "";

                    size_t rlen = strlen(replacement);
                    if (rlen <= remaining) {
                        memcpy(dst, replacement, rlen);
                        dst += rlen;
                        remaining -= rlen;
                    }
                    src = end + 2;
                    continue;
                }
            }
        }
        *dst++ = *src++;
        remaining--;
    }
    return output;
}

static int send_via_shell(const mail_config_t *cfg, const char *to, 
                          const char *subject, const char *body) {
    char cmd[MAX_CMD];
    /* Build sendmail command - subject passed via header in body */
    snprintf(cmd, sizeof(cmd), 
        "printf 'Subject: %s\nFrom: %s\nTo: %s\n\n%s' | sendmail -t",
        subject, cfg->from_addr, to, body);
    return system(cmd);
}

static int send_via_smtp(const mail_config_t *cfg, const char *to,
                         const char *subject, const char *body) {
    /* Simplified SMTP - would use socket in production */
    printf("SMTP[%s:%s] From: %s To: %s Subject: %s\n%s\n",
           cfg->smtp_host, cfg->smtp_port, cfg->from_addr, to, subject, body);
    return 0;
}

int send_welcome_email(const char *to, const char *username, const char *token) {
    mail_config_t cfg;
    if (load_config(&cfg) != 0) {
        fprintf(stderr, "Failed to load mail config\n");
        return -1;
    }

    if (!sanitize_email(to)) {
        fprintf(stderr, "Invalid recipient email\n");
        return -1;
    }

    if (!sanitize_field(username) || !sanitize_field(token)) {
        fprintf(stderr, "Invalid field content\n");
        return -1;
    }

    /* Load template file */
    char tpath[MAX_FIELD * 2];
    snprintf(tpath, sizeof(tpath), "%s/welcome.tpl", cfg.template_dir);

    FILE *f = fopen(tpath, "r");
    if (!f) {
        fprintf(stderr, "Cannot open template: %s\n", tpath);
        return -1;
    }

    char tmpl[MAX_TEMPLATE] = {0};
    fread(tmpl, 1, MAX_TEMPLATE - 1, f);
    fclose(f);

    mail_context_t ctx;
    strncpy(ctx.to, to, MAX_FIELD - 1);
    strncpy(ctx.username, username, MAX_FIELD - 1);
    strncpy(ctx.token, token, MAX_FIELD - 1);
    strncpy(ctx.subject, "Welcome aboard!", MAX_FIELD - 1);

    char *body = render_template(tmpl, &ctx);
    if (!body) return -1;

    int ret;
    if (cfg.use_shell_transport) {
        ret = send_via_shell(&cfg, to, ctx.subject, body);
    } else {
        ret = send_via_smtp(&cfg, to, ctx.subject, body);
    }

    free(body);
    return ret;
}

int main(int argc, char **argv) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <to> <username> <token>\n", argv[0]);
        return 1;
    }
    return send_welcome_email(argv[1], argv[2], argv[3]);
}
